  await setCell(page, 'A1', '2');
  await setCell(page, 'B1', '3');
  await setCell(page, 'C1', '=$A$1+B1');
  await expectCellValue(page, 'C1', '5');

  await cell(page, 'C1').click();
  await page.keyboard.press('Control+C');
